namespace Sortiment.Core.Files;

/// <summary>
/// Identifies a stored file within an <see cref="IFileStorage"/>. Keys are generated by the storage implementation,
/// are opaque to everything else, and are never reused for different content.
/// </summary>
public sealed record StorageKey
{
    /// <summary>
    /// The maximum length of a storage key.
    /// </summary>
    public const int MaxLength = 1024;

    /// <summary>
    /// Wraps a key generated by a storage implementation or read from storage.
    /// </summary>
    /// <param name="value">The key.</param>
    /// <exception cref="ArgumentException">
    /// <paramref name="value"/> is empty, longer than <see cref="MaxLength"/>, or contains control characters.
    /// </exception>
    public StorageKey(string value)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value);
        if (value.Length > MaxLength)
        {
            throw new ArgumentException($"A storage key can be at most {MaxLength} characters long.", nameof(value));
        }

        if (value.Any(char.IsControl))
        {
            throw new ArgumentException("A storage key cannot contain control characters.", nameof(value));
        }

        Value = value;
    }

    /// <summary>
    /// Gets the key as a string.
    /// </summary>
    public string Value { get; }

    /// <inheritdoc />
    public override string ToString() => Value;
}
